// ── Expression IR ────────────────────────────────────────────────────────────

/// Tagged expression union. Mirrors `ir-runtime/src/types.rs::Expression`.
#[derive(Serialize, Deserialize, JsonSchema, Clone, Debug)]
#[serde(tag = "type", rename_all = "camelCase")]

pub enum ExpressionIR {
    // Literals
    #[serde(rename = "literal")]
    Literal { value: JsonValue },

    // Variables & Access
    #[serde(rename = "varRef")]
    VarRef { value: String },
    #[serde(rename = "memberAccess")]
    MemberAccess {
        object: Box<ExpressionIR>,
        properties: Vec<String>,
    },
    #[serde(rename = "indexAccess")]
    IndexAccess {
        object: String,
        index: Box<ExpressionIR>,
    },
    /// Sequence of expression parts (prompt building).
    #[serde(rename = "parts")]
    Parts { value: Vec<ExpressionIR> },
    /// Template string with `{{var}}` segments.
    #[serde(rename = "template")]
    Template { value: Vec<JsonValue> },
    /// Inline object literal `{ key: value, ... }`.
    #[serde(rename = "object")]
    Object {
        value: HashMap<String, ExpressionIR>,
    },
    /// Array literal.
    #[serde(rename = "array")]
    Array { value: Vec<ExpressionIR> },

    // Prompt
    #[serde(rename = "inlinePrompt")]
    InlinePrompt { parts: Vec<JsonValue> },
    #[serde(rename = "promptRef")]
    PromptRef {
        name: String,
        params: Vec<String>,
        args: Vec<ExpressionIR>,
        value: Vec<JsonValue>,
    },
    #[serde(rename = "promptExamples")]
    PromptExamples { examples: Vec<ExamplePairIR> },
    #[serde(rename = "schemaDirective")]
    SchemaDirective { path: String },

    // Conditional (inline template)
    #[serde(rename = "inlineIf")]
    InlineIf {
        condition: JsonValue,
        then: Vec<ExpressionIR>,
        #[serde(rename = "else", default)]
        else_block: Vec<ExpressionIR>,
    },

    // Statements in workflow body
    #[serde(rename = "if")]
    If {
        condition: JsonValue,
        then: Vec<ExpressionIR>,
        #[serde(rename = "else", default)]
        else_block: Vec<ExpressionIR>,
    },
    #[serde(rename = "return")]
    Return { value: Box<ExpressionIR> },
    #[serde(rename = "variableDeclaration")]
    VariableDeclaration {
        name: String,
        value: Box<ExpressionIR>,
    },
    #[serde(rename = "assign")]
    Assign {
        variable: String,
        value: Box<ExpressionIR>,
    },
    #[serde(rename = "parallel")]
    Parallel { body: Vec<ExpressionIR> },
    /// Transfer to a helper: `{ type: "transfer", target: <ExpressionIR>, mode: "..." }`.
    #[serde(rename = "transfer")]
    Transfer {
        target: Box<ExpressionIR>,
        mode: String,
    },

    // Calls
    #[serde(rename = "functionCall")]
    FunctionCall {
        value: String,
        args: Vec<ExpressionIR>,
    },
    #[serde(rename = "helperCall")]
    HelperCall {
        value: String,
        args: Vec<ExpressionIR>,
    },
    #[serde(rename = "promptCall")]
    PromptCall {
        value: String,
        args: Vec<ExpressionIR>,
    },

    // Context
    #[serde(rename = "contextRef")]
    ContextRef { property: String },

    // Binary Ops
    #[serde(rename = "binaryOp")]
    BinaryOp {
        left: Box<ExpressionIR>,
        op: String,
        right: Box<ExpressionIR>,
    },

    /// Wraps another expression (passthrough).
    #[serde(rename = "expression")]
    Expression { value: Box<ExpressionIR> },
}

/// Prompt conversation example pair. Mirrors `ir-runtime::ExamplePair`.
#[derive(Serialize, Deserialize, JsonSchema, Clone, Debug)]

pub struct ExamplePairIR {
    pub user: String,
    pub assistant: String,
}

