// ── Handoff ──────────────────────────────────────────────────────────────────

/// The three handoff modes a helper can operate in.
///
/// Serialized to/from the JSON `helperHandoff` map value:
/// - `Return` → absent (no entry in the map)
/// - `User` → `"user"`
/// - `ThenContinue` → `"thenContinue"`
///
/// Mirrors `ir-runtime/src/runtime/helper_runner.rs::HandoffMode`.
#[derive(Serialize, Deserialize, JsonSchema, Clone, Debug, PartialEq, Default)]
#[serde(rename_all = "camelCase")]

pub enum HandoffKindIR {
    /// Helper result is returned silently to the parent agent (default).
    #[default]
    Return,
    /// Helper streams directly to the user; parent stops afterwards.
    User,
    /// Helper streams directly to the user; parent continues afterwards.
    ThenContinue,
}

impl HandoffKindIR {
    /// Parse from the string stored in the `helperHandoff` map. Absent → `Return`.
    pub fn from_ir_str(s: Option<&str>) -> Self {
        match s {
            Some("user") => HandoffKindIR::User,
            Some("thenContinue") => HandoffKindIR::ThenContinue,
            _ => HandoffKindIR::Return,
        }
    }

    /// Serialize to the string stored in the `helperHandoff` map.
    /// `Return` produces `None` (no map entry).
    pub fn to_ir_str(&self) -> Option<&'static str> {
        match self {
            HandoffKindIR::User => Some("user"),
            HandoffKindIR::ThenContinue => Some("thenContinue"),
            HandoffKindIR::Return => None,
        }
    }
}

// ── Condition IR ─────────────────────────────────────────────────────────────

/// Mirrors `ir-runtime::Condition`.
#[derive(Serialize, Deserialize, JsonSchema, Clone, Debug)]
#[serde(tag = "type", rename_all = "camelCase")]

pub enum ConditionIR {
    #[serde(rename = "comparison")]
    Comparison(ComparisonIR),
    #[serde(rename = "boolean")]
    Boolean { value: Box<ExpressionIR> },
    #[serde(rename = "contextRef")]
    ContextRef { property: String },
    #[serde(rename = "logical")]
    Logical {
        op: String,
        left: Box<ConditionIR>,
        right: Box<ConditionIR>,
    },
}

/// Mirrors `ir-runtime::Comparison`.
#[derive(Serialize, Deserialize, JsonSchema, Clone, Debug)]

pub struct ComparisonIR {
    pub left: Box<ExpressionIR>,
    pub operator: String,
    pub right: Box<ExpressionIR>,
}
